def p(t, s='BodyF'): return Paragraph(t, styles[s])
def bullet(t): return Paragraph('&bull; '+t, styles['BodyF'])
def footer(canvas, doc):
    canvas.saveState(); canvas.setStrokeColor(LINE); canvas.line(1.7*cm,1.35*cm,19.3*cm,1.35*cm)
    canvas.setFont('Arial',8); canvas.setFillColor(MUTED); canvas.drawString(1.7*cm,.85*cm,'FrutLog | Relatorio tecnico do backend')
    canvas.drawRightString(19.3*cm,.85*cm,f'Pagina {doc.page}')
    canvas.restoreState()
def table(rows,widths,head=True):
    t=Table(rows,colWidths=widths,repeatRows=1 if head else 0,hAlign='LEFT')
    st=[('FONTNAME',(0,0),(-1,-1),'Arial'),('FONTSIZE',(0,0),(-1,-1),8.2),('LEADING',(0,0),(-1,-1),11),('TEXTCOLOR',(0,0),(-1,-1),INK),('GRID',(0,0),(-1,-1),.35,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]
    if head: st += [('BACKGROUND',(0,0),(-1,0),NAVY),('FONTNAME',(0,0),(-1,0),'Arial-Bold'),('TEXTCOLOR',(0,0),(-1,0),colors.white)]
    for i in range(1 if head else 0,len(rows)):
        if i%2==0: st.append(('BACKGROUND',(0,i),(-1,i),HexColor('#F7FAFA')))
    t.setStyle(TableStyle(st)); return t

story=[]
story += [Spacer(1,2.2*cm), p('FrutLog', 'TitleF'), p('Relatorio tecnico detalhado do backend', 'TitleF'), Spacer(1,.25*cm), p('Analise de implementacao, arquitetura, dados, seguranca e pontos de evolucao', 'Sub'), Spacer(1,1.1*cm)]
story.append(Table([[p('<b>Escopo analisado</b><br/>server.js, api/[...route].js, scripts/password-hash.js, README.md e migracoes SQL em supabase/.', 'BodyF'),p('<b>Data da analise</b><br/>23 de setembro de 2026', 'BodyF')]],colWidths=[11.4*cm,6.2*cm],style=[('BACKGROUND',(0,0),(-1,-1),PALE),('BOX',(0,0),(-1,-1),.5,HexColor('#B9D9C1')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),10),('RIGHTPADDING',(0,0),(-1,-1),10),('TOPPADDING',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),9)]))
story += [Spacer(1,1.6*cm),p('Resumo executivo','H1F'),p('O backend e uma API Node.js sem framework, com Supabase/PostgREST como persistencia e uma rota dedicada para ingestao de telemetria IoT. A base implementa controles importantes - senha PBKDF2, JWT assinado, comparacao em tempo constante, CORS por allowlist, validacao de entrada e limite basico por IP.','BodyF'),p('<b>Conclusao:</b> a solucao tem um nucleo adequado para um MVP, mas apresenta uma divergencia critica entre a API e o esquema de banco mais recente. Antes de producao, e indispensavel concluir a migracao/adaptacao do modelo de dados e corrigir as rotas operacionais que ainda apontam para as tabelas legadas.','Callout'),Spacer(1,.4*cm),p('Classificacao geral','H2F'),table([[p('Dimensao','Small'),p('Leitura','Small')],[p('Arquitetura','BodyF'),p('Boa separacao entre front-end, API, ponte MQTT e banco.','BodyF')],[p('Seguranca','BodyF'),p('Boas praticas presentes; faltam endurecimentos para escala e operacao.','BodyF')],[p('Dados','BodyF'),p('Modelo operacional mais rico existe, mas a API esta parcialmente desalinhada.','BodyF')],[p('Prontidao','BodyF'),p('MVP controlado; nao recomendado para producao sem plano de correcao.','BodyF')]], [4*cm,13.6*cm])]

story.append(PageBreak()); story += [p('1. Arquitetura e fluxo','H1F'),p('O servidor HTTP em <b>server.js</b> entrega arquivos estaticos do diretorio do front-end e encaminha caminhos iniciados por <b>/api</b> para o handler central. O handler usa somente modulos nativos do Node.js: crypto para autenticacao e fetch para o PostgREST do Supabase.','BodyF'),p('Fluxo principal de telemetria','H2F')]
flow=[[p('<b>1. Sensor</b><br/>Publica no topico MQTT com TLS.','BodyF'),p('<b>2. Ponte privada</b><br/>Assina, valida topico e JSON.','BodyF'),p('<b>3. API FrutLog</b><br/>POST /api/iot/telemetria com chave.','BodyF'),p('<b>4. Supabase</b><br/>Persiste leitura e atualiza dispositivo.','BodyF')]]
story.append(Table(flow,colWidths=[4.35*cm]*4,style=[('BACKGROUND',(0,0),(0,0),HexColor('#E8F0F3')),('BACKGROUND',(1,0),(1,0),HexColor('#EAF4EC')),('BACKGROUND',(2,0),(2,0),HexColor('#FFF4DF')),('BACKGROUND',(3,0),(3,0),HexColor('#F0F2F9')),('BOX',(0,0),(-1,-1),.5,LINE),('INNERGRID',(0,0),(-1,-1),.5,LINE),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),8),('RIGHTPADDING',(0,0),(-1,-1),8),('TOPPADDING',(0,0),(-1,-1),10),('BOTTOMPADDING',(0,0),(-1,-1),10)]))
story += [Spacer(1,.25*cm),p('A ponte MQTT descrita no README e corretamente posicionada fora de uma funcao serverless: ela requer conexao persistente, assinatura controlada e credencial de leitura separada. O navegador nao recebe credenciais de broker nem chave IoT.','Callout'),p('Rotas identificadas','H2F')]
rows=[[p('Metodo e rota','Small'),p('Protecao','Small'),p('Responsabilidade','Small')],[p('GET /api/health','BodyF'),p('Publica + CORS','BodyF'),p('Verifica acesso basico a organizacao no banco.','BodyF')],[p('POST /api/login','BodyF'),p('Limite 10/min por IP','BodyF'),p('Valida matricula/senha e emite JWT de 8 horas.','BodyF')],[p('POST /api/iot/telemetria','BodyF'),p('X-IoT-Key','BodyF'),p('Autoriza dispositivo/sensor e grava leitura.','BodyF')],[p('GET /api/painel-*','BodyF'),p('JWT','BodyF'),p('Monta dados de talhoes, sensores, leituras e inspecoes.','BodyF')],[p('POST /api/plantios','BodyF'),p('JWT: engenheiro/admin','BodyF'),p('Registra plantio.','BodyF')],[p('POST /api/inspecoes, ocorrencias, sensores/problemas','BodyF'),p('JWT: tecnico/admin','BodyF'),p('Registros operacionais.','BodyF')],[p('GET/POST /api/admin/usuarios','BodyF'),p('JWT: admin','BodyF'),p('Lista e cria usuarios.','BodyF')]]
story.append(table(rows,[4.5*cm,4.1*cm,9*cm]))

story.append(PageBreak()); story += [p('2. Autenticacao e seguranca','H1F'),p('A autenticacao e implementada diretamente com primitives criptograficas do Node.js. Senhas sao armazenadas em formato <b>pbkdf2$iteracoes$salt$hash</b>, usando PBKDF2-SHA-256, salt aleatorio de 16 bytes e 210.000 iteracoes. A verificacao usa comparacao em tempo constante. O script password-hash.js permite gerar hashes fora da aplicacao.','BodyF'),p('Controles ja presentes','H2F')]
controls=[[p('Controle','Small'),p('Implementacao observada','Small'),p('Avaliacao','Small')],[p('JWT','BodyF'),p('HMAC-SHA256; claims com id, matricula, nome, perfil, iat e exp; validade de 8h.','BodyF'),p('Adequado para sessao simples.','BodyF')],[p('CORS','BodyF'),p('Permite somente origens em FRONTEND_ORIGIN e localhost local; OPTIONS restrito.','BodyF'),p('Boa allowlist.','BodyF')],[p('IoT','BodyF'),p('Chave X-IoT-Key comparada em tempo constante; sensor, dispositivo e talhao verificados.','BodyF'),p('Bom controle de ingresso.','BodyF')],[p('Entrada','BodyF'),p('JSON limitado a 16 KiB; texto, datas, tipos e valores validados.','BodyF'),p('Boa defesa inicial.','BodyF')],[p('Cabecalhos','BodyF'),p('nosniff e no-store nas respostas JSON.','BodyF'),p('Positivo.','BodyF')],[p('Banco','BodyF'),p('API usa service role; RLS ativado nas migracoes.','BodyF'),p('Exige isolamento rigoroso do servidor.','BodyF')],[p('Rate limit','BodyF'),p('Map em memoria, 10/min no login e 120/min nas demais rotas.','BodyF'),p('Limitado a instancia unica.','BodyF')]]
story.append(table(controls,[3.1*cm,9.2*cm,5.3*cm]))
story += [p('Riscos e recomendacoes de seguranca','H2F'),bullet('<b>Rate limiting:</b> o Map em memoria nao e compartilhado entre instancias e pode crescer indefinidamente. Usar Redis, Upstash ou controle no gateway/reverse proxy.'),bullet('<b>Proxy:</b> x-forwarded-for e aceito sem validacao. Confiar nesse cabecalho apenas quando a aplicacao estiver atras de proxy conhecido; caso contrario, um cliente pode forjar IPs.'),bullet('<b>JWT:</b> nao ha revogacao, refresh token ou identificador de token. Para usuarios desativados apos o login, o token segue valido ate expirar. Introduzir jti/versao de sessao ou curta expiracao com refresh.'),bullet('<b>Segredos:</b> manter SUPABASE_SECRET_KEY, JWT_SECRET e IOT_API_KEY exclusivamente no ambiente do servidor; rotacionar a chave IoT e criar uma chave por ponte/ambiente quando possivel.'),bullet('<b>Auditoria:</b> o modelo operacional cita evento_auditoria, mas as rotas nao registram log de criacao de usuario, login, erro de autorizacao ou alteracao operacional.')]

story.append(PageBreak()); story += [p('3. Dados e integracao com Supabase','H1F'),p('O repositorio contem dois mundos de dados. O arquivo <b>supabase/schema.sql</b> descreve tabelas legadas pluralizadas (usuarios, talhoes, dispositivos_iot, sensores, telemetrias etc.). As migracoes 002-005 introduzem um modelo operacional singular e mais normalizado (organizacao, fazenda, talhao, dispositivo, sensor, leitura_sensor, alerta e outros).','BodyF'),p('Modelo operacional previsto','H2F')]
story.append(table([[p('Camada','Small'),p('Entidades e finalidade','Small')],[p('Contexto','BodyF'),p('organizacao, fazenda, talhao: delimitam propriedade e localizacao.','BodyF')],[p('Cultivo','BodyF'),p('cultura, cultivar, ciclo_cultura, colheita: historico agricola e produtividade.','BodyF')],[p('IoT','BodyF'),p('dispositivo, sensor, leitura_sensor: equipamento, metrica e serie temporal.','BodyF')],[p('Operacao','BodyF'),p('inspecao, regra_alerta, alerta, evento_auditoria: acompanhamento e rastreabilidade.','BodyF')]], [3.6*cm,14*cm]))
story += [p('Integridade e desempenho','H2F'),p('A migracao 003 adiciona indices para filtros de dispositivos, sensores, alertas e ciclos; cria unicidade para regras de alerta; e instala um trigger que impede leitura associada a sensor de outro dispositivo. A migracao 005 traduz dados legados para o novo modelo sem apagar as tabelas antigas. Esses sao bons fundamentos para uma migracao gradual.','BodyF'),p('Divergencias criticas identificadas','H2F')]
div=[[p('Evidencia','Small'),p('Impacto','Small'),p('Acao recomendada','Small')],[p('Ingestao IoT usa dispositivo, sensor e leitura_sensor (novo modelo).','BodyF'),p('Depende de 002/003/005 estarem aplicadas.','BodyF'),p('Manter e testar contra banco migrado.','BodyF')],[p('Login e admin usam usuarios (legado); painel usa talhao/sensor (novo).','BodyF'),p('Aplicacao mistura contratos e pode falhar conforme a ordem de migracao.','BodyF'),p('Padronizar API para usuario, talhao, dispositivo, sensor e inspecao.','BodyF')],[p('POST /plantios e rotas de tecnico usam tabelas pluralizadas, enquanto painel consulta inspecao singular.','BodyF'),p('Registros criados podem nao aparecer no painel ou nem existir na base nova.','BodyF'),p('Mapear payloads e substituir as tabelas legadas por endpoints do modelo operacional.','BodyF')],[p('README menciona dispositivos_iot, telemetrias e sensores; codigo atual de IoT usa nomes singulares.','BodyF'),p('Documentacao operacional pode induzir provisionamento incorreto.','BodyF'),p('Atualizar README junto com a adaptacao.','BodyF')]]
story.append(table(div,[5.3*cm,5.7*cm,6.6*cm]))

story.append(PageBreak()); story += [p('4. Qualidade, operacao e evolucao','H1F'),p('O projeto e deliberadamente enxuto: nao declara dependencias externas e centraliza a logica em um handler. Isso reduz superficie inicial, mas tambem torna a manutencao mais dificil quando crescer. Nao foram localizados testes automatizados do backend, esquema de validacao reutilizavel, logger estruturado ou observabilidade.','BodyF'),p('Pontos tecnicos a observar','H2F')]
story.append(table([[p('Tema','Small'),p('Observacao','Small')],[p('Tratamento de erros','BodyF'),p('A funcao db devolve uma mensagem generica ao cliente, o que protege detalhes, mas nao registra status/corpo do PostgREST para diagnostico. Adicionar logs estruturados sem segredos.','BodyF')],[p('Consultas do painel','BodyF'),p('O endpoint busca ate 500 ultimas leituras e monta joins em memoria. Para volumes maiores, mover agregacoes e alertas para view/RPC SQL paginada.','BodyF')],[p('Requisicoes SQL','BodyF'),p('A query e montada por concatenacao, com encodeURIComponent em identificadores. O risco imediato e reduzido, mas um cliente Supabase ou RPC reduz fragilidade e melhora tipagem.','BodyF')],[p('Cabecalhos HTTP','BodyF'),p('A API adiciona nosniff/no-store. Para a camada HTTP, avaliar CSP, HSTS (em HTTPS) e X-Frame-Options na infraestrutura de entrega.','BodyF')],[p('Static files','BodyF'),p('server.js bloqueia path traversal ao resolver caminho e verificar relativo. O cache esta em no-cache, adequado para desenvolvimento; produzir estrategia de cache com hash de assets em producao.','BodyF')]], [4.2*cm,13.4*cm]))
story += [p('Plano priorizado','H2F')]
plan=[[p('Prioridade','Small'),p('Entrega','Small'),p('Criterio de aceite','Small')],[p('P0 - antes de producao','BodyF'),p('Unificar API e schema operacional; remover dependencia funcional das tabelas plurais.','BodyF'),p('Login, usuarios, painel, plantio e inspecao funcionando em um banco migrado de ponta a ponta.','BodyF')],[p('P0 - antes de producao','BodyF'),p('Corrigir documentacao de provisionamento IoT e validar migracoes em ambiente de homologacao.','BodyF'),p('README, SQL e rotas descrevem os mesmos nomes e contratos.','BodyF')],[p('P1','BodyF'),p('Testes: login, RBAC, telemetria autorizada/negada, validacao e painel.','BodyF'),p('Suite automatizada em CI com banco de teste ou mocks de PostgREST.','BodyF')],[p('P1','BodyF'),p('Observabilidade e rate limiting distribuido.','BodyF'),p('Logs com request-id, metricas de 4xx/5xx e limite compartilhado.','BodyF')],[p('P2','BodyF'),p('Refatorar handler em modulos (auth, iot, painel, admin, repositorios).','BodyF'),p('Responsabilidades separadas e contratos testaveis.','BodyF')]]
story.append(table(plan,[3.2*cm,7.4*cm,7*cm]))
story += [Spacer(1,.2*cm),p('Conclusao final','H2F'),p('A arquitetura proposta para o caminho IoT e sensata, e varios controles essenciais ja estao codificados. A maior fragilidade nao e um componente isolado: e a coexistencia de dois modelos de dados sem uma adaptacao completa da API. Resolver essa fronteira, validar o fluxo completo e estabelecer testes darao ao backend uma base muito mais confiavel para evoluir.','Callout')]

doc=SimpleDocTemplate(OUT,pagesize=A4,rightMargin=1.7*cm,leftMargin=1.7*cm,topMargin=1.55*cm,bottomMargin=1.75*cm,title='Relatorio tecnico do backend - FrutLog',author='Codex')
